rules.logic:
// Idempotent: skip if already injected
if (element.querySelector('.ext-save-btn')) return;

// Get the pin URL from the closest anchor tag
const pinEl = element.closest('[data-test-id="pin"]');
const pinId = pinEl ? pinEl.getAttribute('data-test-pin-id') : null;
const anchor = pinEl ? pinEl.querySelector('a[href*="/pin/"]') : null;
const href = anchor ? anchor.getAttribute('href') : '#';

// Create the button
const btn = document.createElement('a');
btn.className = 'ext-save-btn';
btn.href = href;
btn.target = '_blank';
btn.rel = 'noopener noreferrer';
btn.textContent = '⬆ Save';
btn.title = 'Save this Pin to a board';

// Prevent click from bubbling to the pin card link
btn.addEventListener('click', function(e) {
  e.stopPropagation();
});

// Style the button
btn.style.cssText = `
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 999;
  background: #e60023;
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  padding: 7px 13px;
  border-radius: 24px;
  text-decoration: none;
  box-shadow: 0 2px 8px rgba(0,0,0,0.35);
  cursor: pointer;
  letter-spacing: 0.3px;
  line-height: 1;
  white-space: nowrap;
  border: none;
  outline: none;
  pointer-events: auto;
  transition: background 0.15s, transform 0.1s;
`;

btn.addEventListener('mouseenter', function() {
  btn.style.background = '#ad081b';
  btn.style.transform = 'scale(1.06)';
});
btn.addEventListener('mouseleave', function() {
  btn.style.background = '#e60023';
  btn.style.transform = 'scale(1)';
});

element.appendChild(btn);
